// Hot batch 314: script-binding registrations and a few other functions no route reaches, written by hand from
// `tools.disasm` and verified by synthetic cases (member-table registrations, a string-vector refill, a destructor,
// a child-node rebind and a request setup under a lock).
// No names: none has evidence.
#include "decomp_registry.hpp"
#include "gt/game/hot_common.hpp"
#include "guest_call.hpp"

